CREATE FUNCTION public.biz_admin(_actor uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=_actor AND status='Đang hoạt động') AND (public.is_super_admin(_actor) OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_actor AND role_id='role-admin'))$$;
REVOKE ALL ON FUNCTION public.biz_admin(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.biz_admin(uuid) TO authenticated;
DO $$DECLARE d text;BEGIN
SELECT pg_get_functiondef('public.biz_can(uuid,text)'::regprocedure) INTO d;
d:=replace(d,'IF public.is_super_admin(_actor) THEN RETURN true;END IF;','IF public.is_super_admin(_actor) THEN RETURN true;END IF;');
d:=replace(d,'IF _permission NOT LIKE ''biz.%'' THEN RETURN private.sig_can(_actor,_permission);END IF;', 'IF _permission NOT LIKE ''biz.%'' THEN RETURN private.sig_can(_actor,_permission);END IF; IF public.biz_admin(_actor) THEN RETURN true;END IF; IF _permission=''biz.access_manage'' THEN RETURN false;END IF; IF _permission=''biz.intervene'' THEN RETURN EXISTS(SELECT 1 FROM public.biz_appointments a WHERE a.user_id=_actor AND a.status<>''cancelled'' AND a.started_at<=now() AND (a.ended_at IS NULL OR a.ended_at>now()) AND a.position_snapshot->>''code''=''executive_director'' AND a.position_snapshot->>''business_policy''=''executive'' AND coalesce((a.position_snapshot->>''all_business'')::boolean,false));END IF;');
EXECUTE d;
SELECT pg_get_functiondef('public.biz_all_scope(uuid)'::regprocedure) INTO d;EXECUTE replace(d,'public.is_super_admin(_actor)','public.biz_admin(_actor)');
SELECT pg_get_functiondef('public.biz_appointment_guard()'::regprocedure) INTO d;
d:=replace(d,'IF NEW.scope_kind=''system'' THEN','IF p.all_business AND p.business_policy=''executive'' THEN IF NEW.system_id IS NOT NULL OR NEW.department_id IS NOT NULL OR NEW.team_id IS NOT NULL THEN RAISE EXCEPTION ''Lãnh đạo cấp Khối không gắn vào một Hệ.'';END IF; ELSIF NEW.scope_kind=''system'' THEN');
d:=replace(d,'END=unit AND (NEW.scope_kind<>''individual''','END IS NOT DISTINCT FROM unit AND (NEW.scope_kind<>''individual''');
IF position('Lãnh đạo cấp Khối' IN d)=0 OR position('IS NOT DISTINCT FROM unit' IN d)=0 THEN RAISE EXCEPTION 'Không khớp kiểm tra bổ nhiệm.';END IF;EXECUTE d;
SELECT pg_get_functiondef('public.biz_resolve_position(uuid,uuid,uuid,uuid,timestamptz)'::regprocedure) INTO d;d:=replace(d,'((a.scope_kind=''system'' AND a.system_id=_sys)', '((coalesce((a.position_snapshot->>''all_business'')::boolean,false) AND a.position_snapshot->>''business_policy''=''executive'') OR (a.scope_kind=''system'' AND a.system_id=_sys)');EXECUTE d;
SELECT pg_get_functiondef('public.biz_appointment_save(jsonb)'::regprocedure) INTO d;
d:=replace(d,'OR previous_.user_id<>(_data->>''user_id'')::uuid ','');
d:=replace(d,'ELSE IF replace_ IS NOT NULL THEN', 'ELSE IF nullif(_data->>''legacy_replaces_id'','''') IS NOT NULL THEN PERFORM 1 FROM public.biz_management_assignments WHERE id=(_data->>''legacy_replaces_id'')::uuid AND started_at<start_ AND (ended_at IS NULL OR ended_at>clock_timestamp()) FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION ''Phân công cũ không còn hiệu lực.'';END IF;INSERT INTO public.biz_org_events(actor_id,action,payload) SELECT auth.uid(),''appointment_transition'',jsonb_build_object(''old'',to_jsonb(m),''new'',_data) FROM public.biz_management_assignments m WHERE m.id=(_data->>''legacy_replaces_id'')::uuid;UPDATE public.biz_management_assignments SET ended_at=start_ WHERE id=(_data->>''legacy_replaces_id'')::uuid;END IF; IF replace_ IS NOT NULL THEN');
EXECUTE d;
SELECT pg_get_functiondef('public.biz_approval_override(uuid,integer,text,text,uuid)'::regprocedure) INTO d;d:=replace(d,'public.is_super_admin(auth.uid())','public.biz_can(auth.uid(),''biz.intervene'')');d:=replace(d,'Chỉ Super Admin được can thiệp.','Không có quyền can thiệp đặc biệt.');EXECUTE d;
SELECT pg_get_functiondef('public.biz_approval_adopt(uuid,text,boolean)'::regprocedure) INTO d;d:=replace(d,'public.is_super_admin(auth.uid())','public.biz_can(auth.uid(),''biz.intervene'')');EXECUTE d;
SELECT pg_get_functiondef('public.biz_exception_save(jsonb)'::regprocedure) INTO d;d:=replace(d,'(public.is_super_admin(auth.uid()) OR private.sig_can(auth.uid(),''settings.role''))','public.biz_admin(auth.uid())');EXECUTE d;
SELECT pg_get_functiondef('public.biz_effective_access(uuid)'::regprocedure) INTO d;d:=replace(d,'''biz.dashboard_public'',''biz.view_own''','''biz.intervene'',''biz.access_manage'',''biz.dashboard_public'',''biz.view_own''');d:=replace(d,'WHEN ''system'' THEN (SELECT name FROM public.biz_systems WHERE id=a.system_id)','WHEN ''system'' THEN CASE WHEN coalesce((a.position_snapshot->>''all_business'')::boolean,false) THEN ''Toàn Khối Kinh doanh Sứ Việt'' ELSE (SELECT name FROM public.biz_systems WHERE id=a.system_id) END');EXECUTE d;
END$$;
DROP POLICY IF EXISTS biz_exception_read ON public.biz_access_exceptions;
CREATE POLICY biz_exception_read ON public.biz_access_exceptions FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles u WHERE u.user_id=auth.uid() AND u.role_id=biz_access_exceptions.role_id) OR public.biz_admin(auth.uid()));
COMMENT ON FUNCTION public.biz_admin(uuid) IS 'Trusted existing Base role-admin and Super Admin, business-only authority; never inferred from role display names.';
COMMENT ON FUNCTION public.biz_appointment_save(jsonb) IS 'Atomic appointment transition; legacy_replaces_id explicitly retires one legacy assignment, replaces_id retires one catalog decision. No implicit reassignment of historical approval runs.';